const query = $fromAI('input', 'JSON with oldPath and newPath', 'string');
const ctx = $('Merge Files').item.json;
const owner = ctx.site.owner;
const repo = ctx.site.repo;
const branch = ctx.branch;

let oldPath, newPath;
try {
  const parsed = JSON.parse(query);
  oldPath = parsed.oldPath || parsed.original_file_path;
  newPath = parsed.newPath || parsed.new_file_path;
} catch {
  return JSON.stringify({ error: 'Invalid JSON. Use: {"oldPath": "...", "newPath": "..."}' });
}

if (!oldPath || !newPath) {
  return JSON.stringify({ error: 'Both oldPath and newPath are required' });
}

try {
  // Read old file
  const existing = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/${oldPath}?ref=${branch}`,
    headers: {
      'Authorization': `Bearer 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`,
      'Accept': 'application/vnd.github+json'
    }
  });

  // Create new file
  await this.helpers.httpRequest({
    method: 'PUT',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/${newPath}`,
    headers: {
      'Authorization': `Bearer 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`,
      'Accept': 'application/vnd.github+json',
      'Content-Type': 'application/json'
    },
    body: {
      message: `Rename ${oldPath} to ${newPath} via AutoMate`,
      content: existing.content,
      branch: branch
    }
  });

  // Delete old file
  await this.helpers.httpRequest({
    method: 'DELETE',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/${oldPath}`,
    headers: {
      'Authorization': `Bearer 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`,
      'Accept': 'application/vnd.github+json',
      'Content-Type': 'application/json'
    },
    body: {
      message: `Rename ${oldPath} to ${newPath} via AutoMate (delete old)`,
      sha: existing.sha,
      branch: branch
    }
  });

  return JSON.stringify({ success: true, renamed: { from: oldPath, to: newPath } });
} catch (error) {
  return JSON.stringify({ error: `Failed to rename: ${error.message}` });
}

