const query = $fromAI('input', 'Search pattern or JSON with pattern and path', 'string');
const ctx = $('Merge Files').item.json;
const owner = ctx.site.owner;
const repo = ctx.site.repo;

let pattern, path = '';
try {
  const parsed = JSON.parse(query);
  pattern = parsed.pattern || parsed.query || query;
  path = parsed.path || '';
} catch {
  pattern = query;
}

try {
  const searchQuery = path ? `${pattern} path:${path}` : pattern;
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/search/code?q=${encodeURIComponent(searchQuery)}+repo:${owner}/${repo}`,
    headers: {
      'Authorization': `Bearer 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`,
      'Accept': 'application/vnd.github+json'
    }
  });

  if (response.items?.length > 0) {
    const results = response.items.slice(0, 15).map(item => `- ${item.path}`).join('\n');
    return `Found "${pattern}" in ${response.total_count} files:\n${results}`;
  }
  return `No results found for "${pattern}"`;
} catch (error) {
  return JSON.stringify({ error: error.message });
}

