const query = $fromAI('input', 'URL to fetch', 'string');

let url = query;
try {
  const parsed = JSON.parse(query);
  url = parsed.url || parsed.input || query;
} catch { url = query; }

if (!url.startsWith('http')) {
  url = 'https://' + url;
}

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: url,
    headers: {
      'User-Agent': 'Mozilla/5.0 (compatible; AutoMate/1.0)',
      'Accept': 'text/html,application/json,text/plain'
    }
  });

  let content = typeof response === 'string' ? response : JSON.stringify(response, null, 2);

  // Basic HTML to text
  content = content
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  return `Content from ${url}:\n${content.substring(0, 10000)}`;
} catch (error) {
  return JSON.stringify({ error: `Failed to fetch ${url}: ${error.message}` });
}

const query = $fromAI('input', 'Search query', 'string');

let searchQuery = query;
try {
  const parsed = JSON.parse(query);
  searchQuery = parsed.query || parsed.input || query;
} catch { searchQuery = query; }

// Use DuckDuckGo instant answers API
try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.duckduckgo.com/?q=${encodeURIComponent(searchQuery)}&format=json&no_html=1`,
    headers: {
      'User-Agent': 'AutoMate/1.0'
    }
  });

  let results = [];

  if (response.AbstractText) {
    results.push(`**Summary:** ${response.AbstractText}`);
  }
  if (response.AbstractURL) {
    results.push(`**Source:** ${response.AbstractURL}`);
  }
  if (response.RelatedTopics?.length > 0) {
    results.push('\n**Related:**');
    response.RelatedTopics.slice(0, 5).forEach(topic => {
      if (topic.Text) results.push(`- ${topic.Text}`);
    });
  }

  if (results.length === 0) {
    return `Search for "${searchQuery}" - No instant answer available. Try a more specific query.`;
  }

  return `Search results for "${searchQuery}":\n${results.join('\n')}`;
} catch (error) {
  return JSON.stringify({ error: error.message });
}

const query = $fromAI('input', 'JSON with url and targetPath', 'string');
const ctx = $('Merge Files').item.json;
const owner = ctx.site.owner;
const repo = ctx.site.repo;
const branch = ctx.branch;

let url, targetPath;
try {
  const parsed = JSON.parse(query);
  url = parsed.url || parsed.source_url;
  targetPath = parsed.targetPath || parsed.target_path;
} catch {
  return JSON.stringify({ error: 'Invalid JSON. Use: {"url": "...", "targetPath": "..."}' });
}

if (!url || !targetPath) {
  return JSON.stringify({ error: 'Both url and targetPath are required' });
}

try {
  // Download file
  const fileResponse = await this.helpers.httpRequest({
    method: 'GET',
    url: url,
    encoding: 'arraybuffer'
  });

  const content = Buffer.from(fileResponse).toString('base64');

  // Upload to GitHub
  await this.helpers.httpRequest({
    method: 'PUT',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/${targetPath}`,
    headers: {
      'Authorization': `Bearer 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`,
      'Accept': 'application/vnd.github+json',
      'Content-Type': 'application/json'
    },
    body: {
      message: `Add ${targetPath} via AutoMate`,
      content: content,
      branch: branch
    }
  });

  return JSON.stringify({ success: true, downloaded: url, savedTo: targetPath });
} catch (error) {
  return JSON.stringify({ error: `Failed to download: ${error.message}` });
}

const agentOutput = $input.first().json;
const ctx = $('Merge Files').item.json;

let response = agentOutput.output || '';
let filesChanged = [];
let thinking = [];
let success = true;

// Extract file changes and thinking from intermediate steps
if (agentOutput.intermediateSteps) {
  for (const step of agentOutput.intermediateSteps) {
    // Extract thinking from AI messages
    if (step.action?.log) {
      const logContent = step.action.log;
      // Extract text before tool call as thinking
      const textMatch = logContent.match(/\[\{"index":0,"type":"text","text":"([^"]+)"/);
      if (textMatch) {
        thinking.push(textMatch[1]);
      }
    }

    // Extract file changes
    if (step.action?.tool === 'write_file' && step.observation) {
      try {
        const obs = JSON.parse(step.observation);
        if (obs.success && obs.file) {
          filesChanged.push({ file: obs.file, action: obs.action || 'updated' });
        }
      } catch {}
    }

    if (step.action?.tool === 'delete_file' && step.observation) {
      try {
        const obs = JSON.parse(step.observation);
        if (obs.success) {
          filesChanged.push({ file: obs.deleted, action: 'deleted' });
        }
      } catch {}
    }

    if (step.action?.tool === 'rename_file' && step.observation) {
      try {
        const obs = JSON.parse(step.observation);
        if (obs.success) {
          filesChanged.push({ file: obs.renamed?.to, action: 'renamed' });
        }
      } catch {}
    }
  }
}

// Check for max iterations
if (response.includes('max iterations')) {
  success = false;
  response = 'The request was complex. Some changes may have been made. Please check and try a simpler request if needed.';
}

return [{
  json: {
    success,
    response,
    filesChanged,
    thinking,
    siteId: ctx.siteId,
    conversationId: ctx.conversationId,
    message: ctx.message
  }
}];
